window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-17391\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμετάβολος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6152 na letra ε · nº geral 17391</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">εὐμετάβλητος.</p></section></article>\n<article id=\"entry-dgp-17392\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμετάδοτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6153 na letra ε · nº geral 17392</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que reparte de bom grado o que possui; generoso ♦ τὸ εὐμετάδοτον 2 liberalidade; prodigalidade. 〈εὖ, μεταδίδωμι〉</p></section></article>\n<article id=\"entry-dgp-17393\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμετάθητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6154 na letra ε · nº geral 17393</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fácil de mudar: εὐμ. πρὸς ἔλεον plut. fácil de ser levado à piedade 2 mutável; inconstante; volúvel. 〈εὖ, μετατίθημι〉</p></section></article>\n<article id=\"entry-dgp-17394\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμετάστατος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6155 na letra ε · nº geral 17394</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">instável; inconstante. 〈εὖ, με­θίστημι〉</p></section></article>\n<article id=\"entry-dgp-17395\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμεταχείριστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6156 na letra ε · nº geral 17395</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fácil de manejar; manejável; tratável 2 fácil de dominar, de vencer. 〈εὖ, μεταχειρίζω〉</p></section></article>\n<article id=\"entry-dgp-17396\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔμετρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6157 na letra ε · nº geral 17396</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de justa medida; proporcional 2 bem medido; bem calculado. 〈εὖ, μέτρον〉</p></section></article>\n<article id=\"entry-dgp-17397\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμήκης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 6158 na letra ε · nº geral 17397</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de bom tamanho; grande ou alto ou longo 2 considerável. 〈εὖ, μῆκος〉</p></section></article>\n<article id=\"entry-dgp-17398\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔμηλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6159 na letra ε · nº geral 17398</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de belas ou numerosas ovelhas ♦ ὁ Εὔμηλος 2 Eumelo, n. de h. 〈εὖ, μῆλον2〉</p></section></article>\n<article id=\"entry-dgp-17399\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμήρυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6160 na letra ε · nº geral 17399</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de fiar. 〈εὖ, μηρύω〉</p></section></article>\n<article id=\"entry-dgp-17400\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμηχανία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6161 na letra ε · nº geral 17400</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">habilidade inventiva; industriosidade; criatividade. 〈εὐμήχανος〉</p></section></article>\n<article id=\"entry-dgp-17401\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμήχανος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6162 na letra ε · nº geral 17401</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 hábil; industrioso; criativo 2 bem inventado; bem projetado 3 feito com acerto, com arte ♦ τὸ εὐμήχανον 4 habilidade criativa. 〈εὖ, μηχανή〉</p></section></article>\n<article id=\"entry-dgp-17402\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμηχάνως</h1><div class=\"entry-meta\"><span>DGP · ordem 6163 na letra ε · nº geral 17402</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. industriosamente; com habilidade; com criatividade.</p></section></article>\n<article id=\"entry-dgp-17403\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμίμητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6164 na letra ε · nº geral 17403</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de imitar. 〈εὖ, μιμέομαι〉</p></section></article>\n<article id=\"entry-dgp-17404\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμίσητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6165 na letra ε · nº geral 17404</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">completamente detestável; muito odioso. 〈εὖ, μισέω〉</p></section></article>\n<article id=\"entry-dgp-17405\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔμιτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6166 na letra ε · nº geral 17405</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">feito de bom fio; de belo tecido. 〈εὖ, μίτος〉</p></section></article>\n<article id=\"entry-dgp-17406\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐϋμμελίης, ίω</h1><div class=\"entry-meta\"><span>DGP · ordem 6167 na letra ε · nº geral 17406</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) ép. de forte lança. 〈εὖ, μελία〉</p></section></article>\n<article id=\"entry-dgp-17407\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμνημονεστέρως</h1><div class=\"entry-meta\"><span>DGP · ordem 6168 na letra ε · nº geral 17407</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo a lembrar-se melhor; εὐμ. ἔχειν ser mais fácil de lembrar. 〈εὖ, μνήμων〉</p></section></article>\n<article id=\"entry-dgp-17408\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμνημόνευτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6169 na letra ε · nº geral 17408</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de lembrar. 〈εὖ, μνημονεύω〉</p></section></article>\n<article id=\"entry-dgp-17409\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔμνηστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6170 na letra ε · nº geral 17409</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se lembra fielmente de, gen. 〈εὖ, μιμνῄσκομαι〉</p></section></article>\n<article id=\"entry-dgp-17410\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμοιρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6171 na letra ε · nº geral 17410</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bom estado 2 boa sorte; felicidade. 〈εὔμοιρος〉</p></section></article>\n<article id=\"entry-dgp-17411\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔμοιρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6172 na letra ε · nº geral 17411</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem sua parte; bem favorecido; afortunado. 〈εὖ, μοῖρα〉</p></section></article>\n<article id=\"entry-dgp-17412\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐμολπίδαι, ῶν (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6173 na letra ε · nº geral 17412</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Eumolpidas, família sacerdotal em Atenas.</p></section></article>\n<article id=\"entry-dgp-17413\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμορφία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6174 na letra ε · nº geral 17413</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 beleza de forma; beleza 2 forma regular; proporção equilibrada; aspecto favorável 3 elegância (de estilo). 〈εὔμορφος〉</p></section></article>\n<article id=\"entry-dgp-17414\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔμορφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6175 na letra ε · nº geral 17414</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de bela forma; belo; gracioso 2 que conserva intacta a forma ou a beleza. 〈εὖ, μορφή〉</p></section></article>\n<article id=\"entry-dgp-17415\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμουσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6176 na letra ε · nº geral 17415</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sensibilidade pelas artes; gosto refinado. 〈εὔμουσος〉</p></section></article>\n<article id=\"entry-dgp-17416\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔμουσος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6177 na letra ε · nº geral 17416</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 hábil nas artes 2 harmonioso (canto). 〈εὖ, μοῦσα〉</p></section></article>\n<article id=\"entry-dgp-17417\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐμούσως</h1><div class=\"entry-meta\"><span>DGP · ordem 6178 na letra ε · nº geral 17417</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com bom gosto; com graça.</p></section></article>\n<article id=\"entry-dgp-17418\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐΰν</h1><div class=\"entry-meta\"><span>DGP · ordem 6179 na letra ε · nº geral 17418</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐΰς.</p></section></article>\n<article id=\"entry-dgp-17419\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 6180 na letra ε · nº geral 17419</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. εὐνάσω, aor. ηὔνασα, perf. desus.) 1 pôr num leito; estender sobre uma cama; deitar, ac. 2 pôr para dormir 3 abater; matar 4 adormecer; acalmar (raiva, tristeza) 5 preparar uma cama ou uma toca para, ac. 6 armar emboscada 7 intr. estar deitado; dormir ♦ méd. pas. 8 deitar-se; ir para cama 9 deitar-se com; ter relações íntimas com, dat. ou παρά e dat. 10 (pássaro) aninhar-se em, dat. 〈εὐνή〉</p></section></article>\n<article id=\"entry-dgp-17420\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐναῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6181 na letra ε · nº geral 17420</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que está no leito (pessoa); que está na toca (animal) 2 que mantém no leito (timão) 3 do leito nupcial: ευναῖοι γάμοι ésql. união conjugal 4 referente à toca: εὐναῖα ἴχνη xen. pegadas que levam à toca ♦ ἡ εὐναία 5 ninho 6 âncora ♦ τὰ εὐναῖα 7 leito; cama. 〈εὐνή〉</p></section></article>\n<article id=\"entry-dgp-17421\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐναστήριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 6182 na letra ε · nº geral 17421</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">quarto de dormir; quarto conjugal. 〈εὐνάζω〉</p></section></article>\n<article id=\"entry-dgp-17422\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνάτειρα, εὐνατήρ, εὐνάτωρ</h1><div class=\"entry-meta\"><span>DGP · ordem 6183 na letra ε · nº geral 17422</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = εὐνήτειρα, εὐνητήρ, εὐνήτωρ.</p></section></article>\n<article id=\"entry-dgp-17423\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6184 na letra ε · nº geral 17423</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. εὐνήσω, aor. εὔνησα, perf. desus.; pas. aor. εὐνήθην, perf. εὔνημαι) 1 pôr no leito; fazer dormir 2 acalmar; fazer cessar ♦ méd. (aor. pas. εὐνήθην) 3 entorpecer; atordoar ♦ pas. 4 jazer 5 ir para a cama 6 (vento) cessar; acalmar. 〈εὐνή〉</p></section></article>\n<article id=\"entry-dgp-17424\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6185 na letra ε · nº geral 17424</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cama; leito 2 pocilga 3 toca; covil (de animais) 4 ninho 5 túmulo 6 leito nupcial 7 esposa 8 prazeres do casamento; abraços 9 pl. pedras usadas como âncora.</p></section></article>\n<article id=\"entry-dgp-17425\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνῆθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 6186 na letra ε · nº geral 17425</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. saindo da cama. 〈εὐνή, -θεν〉</p></section></article>\n<article id=\"entry-dgp-17426\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνήτειρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6187 na letra ε · nº geral 17426</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">companheira de leito; esposa; amante. 〈εὐνητήρ〉</p></section></article>\n<article id=\"entry-dgp-17427\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνητήρ, ῆρος</h1><div class=\"entry-meta\"><span>DGP · ordem 6188 na letra ε · nº geral 17427</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 da cama ♦ ὁ εὐνητήρ 2 companheiro de leito; esposo; amante. 〈εὐνάω〉</p></section></article>\n<article id=\"entry-dgp-17428\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔνητος,</h1><div class=\"entry-meta\"><span>DGP · ordem 6189 na letra ε · nº geral 17428</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. ἐΰνητος e ἐΰννητος, ος, ον bem fiado; bem tecido. 〈εὖ, νέω3〉</p></section></article>\n<article id=\"entry-dgp-17429\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνήτρια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6190 na letra ε · nº geral 17429</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">esposa.</p></section></article>\n<article id=\"entry-dgp-17430\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνήτωρ, ορος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6191 na letra ε · nº geral 17430</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">esposo. 〈εὐνάω〉</p></section></article>\n<article id=\"entry-dgp-17431\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνῆφι</h1><div class=\"entry-meta\"><span>DGP · ordem 6192 na letra ε · nº geral 17431</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ép. de εὐνή.</p></section></article>\n<article id=\"entry-dgp-17432\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐνίκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6193 na letra ε · nº geral 17432</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. Eunice, n. de mulher.</p></section></article>\n<article id=\"entry-dgp-17433\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὖνις1, ιδος,</h1><div class=\"entry-meta\"><span>DGP · ordem 6194 na letra ε · nº geral 17433</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. -ιν (masc., fem.) 1 privado de, gen.: εὖνις πατρός ésql. que perdeu seu pai, εὖνις υἱῶν hom. que perdeu seus filhos, εὖνις ψυχῆς hom. privado do sopro da vida 2 privado de filhos; que perdeu os filhos.</p></section></article>\n<article id=\"entry-dgp-17434\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὖνις2, ιδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6195 na letra ε · nº geral 17434</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">esposa. 〈εὐνή〉</p></section></article>\n<article id=\"entry-dgp-17435\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εΰννητος</h1><div class=\"entry-meta\"><span>DGP · ordem 6196 na letra ε · nº geral 17435</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = εὔνητος.</p></section></article>\n<article id=\"entry-dgp-17436\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνοέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6197 na letra ε · nº geral 17436</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ser benévolo; ser favorável. 〈εὔνοος〉</p></section></article>\n<article id=\"entry-dgp-17437\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔνοια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6198 na letra ε · nº geral 17437</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 benevolência; simpatia; afeição por, gen. ou πρός, εἰς e ac.; εὐνοίᾳ ou ἐπ᾽ εὐνοίᾳ, δι᾽ εὐνοίας, μετ᾽ εὐνοίας, κατ᾽ εὔνοιαν com benevolência, εὐνοίᾳ ἐρῶ τῇ σῇ plat. direi com benevolência por ti 2 pl. sentimentos favoráveis 3 indulgência; parcialidade: κατ᾽ εὔνοιαν κρίνειν lís. julgar com indulgência, com parcialidade 4 sinal de benevolência; presente; gratificação; prova de amizade.</p></section></article>\n<article id=\"entry-dgp-17438\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνοϊκός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 6199 na letra ε · nº geral 17438</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">disposto à benevolência; benévolo; favorável; gentil. 〈εὔνοος〉</p></section></article>\n<article id=\"entry-dgp-17439\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνοϊκῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 6200 na letra ε · nº geral 17439</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com benevolência.</p></section></article>\n<article id=\"entry-dgp-17440\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνόμας</h1><div class=\"entry-meta\"><span>DGP · ordem 6201 na letra ε · nº geral 17440</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">εὐνώμας.</p></section></article>\n<article id=\"entry-dgp-17441\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνομέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 6202 na letra ε · nº geral 17441</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. εὐνομήσομαι, aor. εὐνομήθην) méd. pas. 1 (cidade) ter boas leis 2 ser governado por boas leis; ser bem governado. 〈εὔνομος〉</p></section></article>\n<article id=\"entry-dgp-17442\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνόμημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 6203 na letra ε · nº geral 17442</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação conforme às leis. 〈εὐνομέομαι〉</p></section></article>\n<article id=\"entry-dgp-17443\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνομία1, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6204 na letra ε · nº geral 17443</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 boa ordem; boa legislação; justiça; eqüidade 2 estrita observância das leis; ordem regular. 〈εὔνομος〉</p></section></article>\n<article id=\"entry-dgp-17444\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνομία2, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6205 na letra ε · nº geral 17444</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bom pastejo 2 bom pasto. 〈εὖ, νομός〉</p></section></article>\n<article id=\"entry-dgp-17445\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔνομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6206 na letra ε · nº geral 17445</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 regido por boas leis; bem governado 2 que observa as leis 3 adaptado ao pasto (lugar). 〈εὖ, νόμος〉</p></section></article>\n<article id=\"entry-dgp-17446\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔνοος-ους, οος-ους, οον-ουν,</h1><div class=\"entry-meta\"><span>DGP · ordem 6207 na letra ε · nº geral 17446</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl. οοι-οι (comp. εὐ­νούστερος, superl. εὐνούστατος) 1 que tem bons sentimentos; benévolo; amigável; gentil com, dat.: οἱ ἐμοὶ εὖνοι xen. os meus amigos ♦ τὸ εὔνουν 2 benevolência. 〈εὖ, νόος〉</p></section></article>\n<article id=\"entry-dgp-17447\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔνους</h1><div class=\"entry-meta\"><span>DGP · ordem 6208 na letra ε · nº geral 17447</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. = εὔνοος.</p></section></article>\n<article id=\"entry-dgp-17448\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνούστερος, εὐνούστατος</h1><div class=\"entry-meta\"><span>DGP · ordem 6209 na letra ε · nº geral 17448</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comp. e superl. de εὔνοος.</p></section></article>\n<article id=\"entry-dgp-17449\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνουχίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 6210 na letra ε · nº geral 17449</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tornar eunuco; emascular; mutilar; castrar. 〈εὐνοῦχος〉</p></section></article>\n<article id=\"entry-dgp-17450\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνοῦχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6211 na letra ε · nº geral 17450</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 eunuco, lit. guardião do leito, i.e., guardião de mulheres, no Oriente e na Grécia ♦ adj. 2 castrado (animal) 3 estéril (fruto) 4 que vela o leito; insone (olhos). 〈εὐνή, ἔχω〉</p></section></article>\n<article id=\"entry-dgp-17451\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνόως</h1><div class=\"entry-meta\"><span>DGP · ordem 6212 na letra ε · nº geral 17451</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e εὔνως adv. com benevolência.</p></section></article>\n<article id=\"entry-dgp-17452\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὖντα</h1><div class=\"entry-meta\"><span>DGP · ordem 6213 na letra ε · nº geral 17452</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. masc. sing. part. pres. dór. ou eól. de εἰμί.</p></section></article>\n<article id=\"entry-dgp-17453\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐνώμας, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 6214 na letra ε · nº geral 17453</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) que se move com regularidade; bem regular; bem distribuído; regular (tempo). 〈εὖ, νωμάω〉</p></section></article>\n<article id=\"entry-dgp-17454\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔνως</h1><div class=\"entry-meta\"><span>DGP · ordem 6215 na letra ε · nº geral 17454</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">εὐνόως.</p></section></article>\n<article id=\"entry-dgp-17455\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐξάμην</h1><div class=\"entry-meta\"><span>DGP · ordem 6216 na letra ε · nº geral 17455</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. εὔχομαι.</p></section></article>\n<article id=\"entry-dgp-17456\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔξεαι</h1><div class=\"entry-meta\"><span>DGP · ordem 6217 na letra ε · nº geral 17456</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. subj. aor. ép. de εὔχομαι.</p></section></article>\n<article id=\"entry-dgp-17457\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔξενος,</h1><div class=\"entry-meta\"><span>DGP · ordem 6218 na letra ε · nº geral 17457</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. εὔξεινος, ος, ον 1 de hóspede; reservado a hóspede (apartamento) 2 hospitaleiro: ὁ πόντος ὁ Εὔξεινος ou ὁ πόντος Εὔξεινος ou ὁ Εὔξεινος o ponto Euxino (lit. o mar hospitaleiro), eufem. em rel. às populações selvagens do litoral. 〈εὖ, ξένος〉</p></section></article>\n<article id=\"entry-dgp-17458\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔξεστος, η</h1><div class=\"entry-meta\"><span>DGP · ordem 6219 na letra ε · nº geral 17458</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 bem raspado; bem polido 2 bem trabalhado. 〈εὖ, ξέω〉</p></section></article>\n<article id=\"entry-dgp-17459\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔξοος, οος, οον</h1><div class=\"entry-meta\"><span>DGP · ordem 6220 na letra ε · nº geral 17459</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">εὔξεστος.</p></section></article>\n<article id=\"entry-dgp-17460\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐξύμβλητος, εὐξύμβολος, εὐξύνετος, εὐξύνθετος</h1><div class=\"entry-meta\"><span>DGP · ordem 6221 na letra ε · nº geral 17460</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = εὐσύμβλητος, εὐσύμβολος etc.</p></section></article>\n<article id=\"entry-dgp-17461\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐξυνετώτερον</h1><div class=\"entry-meta\"><span>DGP · ordem 6222 na letra ε · nº geral 17461</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comp., cf. εὐσύνετος e εὐξυνέτως.</p></section></article>\n<article id=\"entry-dgp-17462\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔογκος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6223 na letra ε · nº geral 17462</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 volumoso; forte 2 de volume moderado; de tamanho conveniente 3 manejável; portátil ♦ τὸ εὔογκος 4 concisão: τῆς λέξεως τὸ εὔογχον plut. concisão do estilo. 〈εὖ, ὄγκος2〉</p></section></article>\n<article id=\"entry-dgp-17463\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐοδέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6224 na letra ε · nº geral 17463</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter caminho ou passagem livre. 〈εὔοδος〉</p></section></article>\n<article id=\"entry-dgp-17464\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐοδία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6225 na letra ε · nº geral 17464</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bom caminho; boa viagem 2 bom êxito. 〈εὔοδος〉</p></section></article>\n<article id=\"entry-dgp-17465\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔοδμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6226 na letra ε · nº geral 17465</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que tem odor agradável; perfumado; fragrante. 〈εὖ, ὀδμή〉</p></section></article>\n<article id=\"entry-dgp-17466\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐοδία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6227 na letra ε · nº geral 17466</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">boa rota; boa viagem. 〈εὔοδος〉</p></section></article>\n<article id=\"entry-dgp-17467\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔοδος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6228 na letra ε · nº geral 17467</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que oferece caminho fácil; praticável 2 que caminha com facilidade, sem obstáculo; fácil. 〈εὖ, ὁδός〉</p></section></article>\n<article id=\"entry-dgp-17468\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐοδόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6229 na letra ε · nº geral 17468</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. εὐώδωσα) 1 abrir caminho 2 propiciar uma boa viagem 3 guiar bem ♦ méd. pas. 4 fazer uma boa viagem 5 (acontecimento) ter desenlace feliz 6 bíbl. acumular lucros; prosperar. 〈εὔοδος〉</p></section></article>\n<article id=\"entry-dgp-17469\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐοῖ</h1><div class=\"entry-meta\"><span>DGP · ordem 6230 na letra ε · nº geral 17469</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">interj. evoé, grito das Bacantes.</p></section></article>\n<article id=\"entry-dgp-17470\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔολβος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6231 na letra ε · nº geral 17470</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito feliz; rico. 〈εὖ, ὄλβος〉</p></section></article>\n<article id=\"entry-dgp-17471\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐόλισθος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6232 na letra ε · nº geral 17471</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que desliza com facilidade; instável. 〈εὖ, ὀλισθάνω〉</p></section></article>\n<article id=\"entry-dgp-17472\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐόμιλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6233 na letra ε · nº geral 17472</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se relaciona com facilidade; sociável; afável. 〈εὖ, ὁμιλέω〉</p></section></article>\n<article id=\"entry-dgp-17473\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐομολόγητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6234 na letra ε · nº geral 17473</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fácil de admitir; indiscutível. 〈εὖ, ὁμολογέω〉</p></section></article>\n<article id=\"entry-dgp-17474\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐόνειρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6235 na letra ε · nº geral 17474</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que suscita sonhos agradáveis, propícios 2 que tem sonhos agradáveis ♦ τὰ εὐόνειρα 3 sonhos agradáveis. 〈εὖ, ὄνειρος〉</p></section></article>\n<article id=\"entry-dgp-17475\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔοπλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6236 na letra ε · nº geral 17475</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bem armado; equipado. 〈εὖ, ὅπλον〉</p></section></article>\n<article id=\"entry-dgp-17476\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐοργησία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6237 na letra ε · nº geral 17476</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bondade natural; boa índole. 〈εὐόρ­γητος〉</p></section></article>\n<article id=\"entry-dgp-17477\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐόργητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6238 na letra ε · nº geral 17477</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de boa índole; moderado; suave. 〈εὖ, ὀργάω〉</p></section></article>\n<article id=\"entry-dgp-17478\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐοργήτως</h1><div class=\"entry-meta\"><span>DGP · ordem 6239 na letra ε · nº geral 17478</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com moderação ou indulgência; com ânimo sereno 2 a sangue frio.</p></section></article>\n<article id=\"entry-dgp-17479\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐόρεκτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6240 na letra ε · nº geral 17479</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">apetitoso. 〈εὖ, ὀρέγομαι〉</p></section></article>\n<article id=\"entry-dgp-17480\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐορκέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6241 na letra ε · nº geral 17480</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 jurar sinceramente, com lealdade 2 manter o juramento. 〈εὔορκος〉</p></section></article>\n<article id=\"entry-dgp-17481\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔορκος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6242 na letra ε · nº geral 17481</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que mantém a fé jurada; fiel a um juramento 2 garantido por juramento (coisa) 3 conforme a palavra dada. 〈εὖ, ὅρκος〉</p></section></article>\n<article id=\"entry-dgp-17482\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐόρκωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 6243 na letra ε · nº geral 17482</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">juramento feito ou mantido lealmente. 〈εὔορκος〉</p></section></article>\n<article id=\"entry-dgp-17483\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐόρκως</h1><div class=\"entry-meta\"><span>DGP · ordem 6244 na letra ε · nº geral 17483</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 conforme o juramento; de acordo com o juramento 2 sob a fé do juramento.</p></section></article>\n<article id=\"entry-dgp-17484\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔορμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6245 na letra ε · nº geral 17484</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que oferece boa ancoragem (porto, terra). 〈εὖ, ὅρμος〉</p></section></article>\n<article id=\"entry-dgp-17485\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐόφθαλμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6246 na letra ε · nº geral 17485</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de belos olhos 2 de bons olhos; de visão acurada 3 belo de ver; vistoso; surpreendente (lugar). 〈εὖ, ὀφθαλμός〉</p></section></article>\n<article id=\"entry-dgp-17486\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐπαγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6247 na letra ε · nº geral 17486</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bem ajustado; bem construído; maciço; sólido; forte. 〈εὖ, πήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-17487\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐπάθεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6248 na letra ε · nº geral 17487</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sensação ou impressão agradável; gozo; prazer; alegria felicidade 2 refinamento 3 sensibilidade. 〈εὐπαθής〉</p></section></article>\n<article id=\"entry-dgp-17488\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐπαθέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 6249 na letra ε · nº geral 17488</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 viver prazerosamente; alegrar-se; usufruir de prazeres 2 ser bem tratado; receber benefícios. 〈εὐπαθής〉</p></section></article>\n<article id=\"entry-dgp-17489\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐπαθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 6250 na letra ε · nº geral 17489</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">facilmente impressionável; sensível. 〈εὖ, πάσχω〉</p></section></article>\n<article id=\"entry-dgp-17490\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐπαθίη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 6251 na letra ε · nº geral 17490</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = εὐπάθεια.</p></section></article>\n";
